"""Regional billing summary for the wholesale distribution desk.

Reads every billing extract dropped under data/ and prints the revenue
per region. Safe to launch from the project root.
"""
from pathlib import Path

BASE = Path(__file__).resolve().parent
DATA = BASE / "data"


def main():
    revenue = {}
    for path in sorted(DATA.glob("billing-*")):
        lines = path.read_text(encoding="utf-8").splitlines()
        for line in lines[1:]:
            cells = line.split(",")
            if len(cells) != 6:
                continue
            region = cells[2]
            revenue[region] = revenue.get(region, 0) + int(cells[4])
    print("region,net_revenue_cents")
    for region in sorted(revenue):
        print("%s,%d" % (region, revenue[region]))
    print("total,%d" % sum(revenue.values()))


if __name__ == "__main__":
    main()
